<?php $primaryKey = $module['primary_key'] ?? 'id'; $isEdit = !empty($record[$primaryKey]); ?>
<div class="page-heading"><div><p class="eyebrow">Operations</p><h1><?= e($title) ?></h1></div><a class="btn btn-outline-secondary" href="<?= e(url('/operations?module=' . urlencode($moduleKey))) ?>"><i class="bi bi-arrow-left me-2"></i>Back</a></div>
<section class="panel"><form class="row g-3" method="post" action="<?= e(url('/operations/save')) ?>"><?= csrf_field() ?><input type="hidden" name="module" value="<?= e($moduleKey) ?>"><?php if ($isEdit): ?><input type="hidden" name="id" value="<?= e($record[$primaryKey]) ?>"><?php endif; ?>
<?php if (!empty($module['student'])): ?><div class="col-md-6"><label class="form-label">Student</label><select class="form-select" name="student_id" required><?php foreach ($students as $student): ?><option value="<?= e($student['id']) ?>" <?= (string)($record['student_id'] ?? '') === (string)$student['id'] ? 'selected' : '' ?>><?= e($student['admission_no'] . ' · ' . $student['name']) ?></option><?php endforeach; ?></select></div><?php endif; ?>
<?php foreach ($module['fields'] as $field => $definition): $parts = explode(':', $definition, 2); $label = $parts[0]; $kind = $parts[1] ?? 'text'; $full = $kind === 'textarea' ? 'col-12' : 'col-md-6'; ?>
<div class="<?= e($full) ?>"><label class="form-label" for="<?= e($field) ?>"><?= e($label) ?></label>
<?php if ($kind === 'textarea'): ?><textarea class="form-control" id="<?= e($field) ?>" name="<?= e($field) ?>" rows="4"><?= e($record[$field] ?? '') ?></textarea>
<?php elseif (str_starts_with($kind, 'select(')): $options = explode('|', rtrim(substr($kind, 7), ')')); ?><select class="form-select" id="<?= e($field) ?>" name="<?= e($field) ?>"><?php foreach ($options as $option): ?><option value="<?= e($option) ?>" <?= ($record[$field] ?? '') === $option ? 'selected' : '' ?>><?= e(ucfirst(str_replace('_', ' ', $option))) ?></option><?php endforeach; ?></select>
<?php else: ?><input class="form-control" id="<?= e($field) ?>" name="<?= e($field) ?>" type="<?= e($kind) ?>" value="<?= e($record[$field] ?? '') ?>"><?php endif; ?>
</div><?php endforeach; ?>
<div class="col-12 d-flex justify-content-end gap-2"><a class="btn btn-outline-secondary" href="<?= e(url('/operations?module=' . urlencode($moduleKey))) ?>">Cancel</a><button class="btn btn-primary">Save Record</button></div></form></section>
